(function(){
  var MAP = {
    "christmas-light-installation-hero": "data:image/webp;base64,",
    "christmas-tree-canopy-wrapping": "data:image/webp;base64,",
    "commercial-hoa-holiday-lighting": "data:image/webp;base64,",
    "godoys-wolves-christmas-lights-flyer": "data:image/webp;base64,"
  };
  function patchImages() {
    var imgs = document.querySelectorAll('img');
    for (var i = 0; i < imgs.length; i++) {
      var img = imgs[i];
      var src = img.getAttribute('src') || '';
      for (var k in MAP) {
        if (src.indexOf(k) !== -1) {
          img.removeAttribute('srcset');
          img.removeAttribute('srcSet');
          if (img.src !== MAP[k]) img.src = MAP[k];
        }
      }
    }
    var links = document.querySelectorAll('a[href*="godoys-wolves-christmas-lights-flyer"]');
    for (var j = 0; j < links.length; j++) {
      var a = links[j];
      a.setAttribute('href', '/godoys-wolves-preview/downloads/godoys-wolves-christmas-lights-flyer.html');
      a.removeAttribute('download');
      a.setAttribute('target', '_blank');
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', patchImages);
  } else {
    patchImages();
  }
  setTimeout(patchImages, 150);
  setTimeout(patchImages, 600);
  if (typeof MutationObserver !== 'undefined') {
    var obs = new MutationObserver(patchImages);
    obs.observe(document.documentElement, { childList: true, subtree: true });
  }
})();
